 def test_every_gif_and_static_frame_loads_on_phone_and_tablet_without_external_assets(self):
  from PIL import Image
  for file in (ROOT/'web/umbra/arcade').glob('*.gif'):
   im=Image.open(file);self.assertEqual(im.n_frames,12);frames=set()
   for index in range(im.n_frames):im.seek(index);frames.add(im.convert('RGB').tobytes());self.assertEqual(im.info['duration'],240)
   self.assertGreater(len(frames),1)
  p=self.page();self.tab(p,'settings');p.locator('#umbra-arcade-archive summary').click();p.wait_for_selector('#umbra-arcade-gallery button')
