   p.set_viewport_size(size)
   for button in p.locator('#umbra-arcade-gallery button').all():button.click();p.wait_for_function('(()=>{const i=document.querySelector("#umbra-arcade-preview");return i.complete&&i.naturalWidth===128&&i.dataset.format==="gif";})()');self.assertIn('FICTIONAL',p.locator('#umbra-arcade-caption').inner_text())
