 def test_timer_http_auth_validation_reconfigure_and_unpair_safety(self):
  import urllib.request,urllib.error
  def post(path,data,auth=True,origin=None):
   headers={'Content-Type':'application/json'}
   if auth:headers['Authorization']='Bearer test-client'
   if origin:headers['Origin']=origin
   request=urllib.request.Request(self.url+'/api/'+path,json.dumps(data).encode(),headers)
   try:
    with urllib.request.urlopen(request) as r:return r.status,json.load(r)
   except urllib.error.HTTPError as e:return e.code,json.load(e)
  self.assertEqual(post('tv/timer',{'minutes':15},False)[0],401);self.assertEqual(post('tv/timer',{'minutes':15},origin='https://invalid.example')[0],403)
  for value in [True,1,0,'15',None]:self.assertEqual(post('tv/timer',{'minutes':value})[0],400)
  self.assertEqual(post('tv/timer',{'minutes':15})[0],200);old=self.m.TV_SERVICE.timer.function;self.assertEqual(post('tv/config',{'ip':'192.168.1.100'})[0],200);old();self.assertEqual(self.calls,[]);post('tv/timer',{'minutes':15});old=self.m.TV_SERVICE.timer.function;post('unpair',{});old();self.assertEqual(self.calls,[]);self.assertEqual(post('tv/key',{'key':'home'})[0],401)
